SELECT p.gender, d.icd_code, d.icd_version, s.stay_id, s.intime, s.outtime, COUNT(l.labevent_id) AS labevent_count, rank() OVER (PARTITION BY p.gender, d.icd_code, d.icd_version, s.stay_id ORDER BY s.intime) AS rank FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN icustays s ON a.subject_id = s.subject_id LEFT JOIN labevents l ON (l.subject_id = s.subject_id AND l.hadm_id = s.stay_id) AND l.charttime BETWEEN s.intime AND s.outtime WHERE p.anchor_age >= 82 AND p.gender = 'F' AND a.admission_type = 'ACS' AND s.stay_id IN (SELECT stay_id FROM icustays WHERE length_of_stay BETWEEN 1 AND 4) AND (s.intime - a.admittime) BETWEEN 0 AND 8 GROUP BY p.gender, d.icd_code, d.icd_version, s.stay_id, s.intime, s.outtime ORDER BY p.gender, d.icd_code, d.icd_version, s.stay_id, rank NULLS LAST;